CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','placement')), email_verified BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS email_verifications (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, code_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- For databases created before email verification existed (existing users stay able to log in):
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='email_verified') THEN ALTER TABLE users ADD COLUMN email_verified BOOLEAN NOT NULL DEFAULT false; UPDATE users SET email_verified=true; END IF; END $$;
CREATE TABLE IF NOT EXISTS student_profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, college TEXT NOT NULL DEFAULT '', branch TEXT NOT NULL DEFAULT '', year INTEGER NOT NULL DEFAULT 1, cgpa NUMERIC(3,1) NOT NULL DEFAULT 0, consent_share BOOLEAN NOT NULL DEFAULT false, resume_name TEXT, resume_text TEXT NOT NULL DEFAULT '', resume_skills TEXT[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS password_resets (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT UNIQUE NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS internships (internship_id TEXT PRIMARY KEY, title TEXT NOT NULL, company TEXT NOT NULL, company_type TEXT, location TEXT, mode TEXT, stipend_inr_month INTEGER, duration_months INTEGER, deadline DATE, allowed_branches TEXT[] NOT NULL DEFAULT '{}', allowed_years INTEGER[] NOT NULL DEFAULT '{}', min_cgpa NUMERIC(3,1), apply_url TEXT NOT NULL, source TEXT NOT NULL, data_status TEXT);
CREATE TABLE IF NOT EXISTS internship_skills (internship_id TEXT REFERENCES internships ON DELETE CASCADE, skill TEXT NOT NULL, min_score INTEGER NOT NULL, weight NUMERIC NOT NULL, PRIMARY KEY(internship_id,skill));
CREATE TABLE IF NOT EXISTS questions (question_id TEXT PRIMARY KEY, skill TEXT NOT NULL, difficulty TEXT NOT NULL, weight INTEGER NOT NULL, question TEXT NOT NULL, options JSONB NOT NULL, correct_option TEXT NOT NULL, explanation TEXT);
CREATE TABLE IF NOT EXISTS resources (id BIGSERIAL PRIMARY KEY, skill TEXT NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id BIGSERIAL PRIMARY KEY, code CHAR(6) UNIQUE NOT NULL, title TEXT NOT NULL, per_skill INTEGER NOT NULL, time_limit_minutes INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_by BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS attempts (id UUID PRIMARY KEY, user_id BIGINT REFERENCES users(id), mode TEXT NOT NULL, status TEXT NOT NULL, question_map JSONB NOT NULL, answers JSONB NOT NULL DEFAULT '[]', per_question_seconds JSONB NOT NULL DEFAULT '[]', started_at TIMESTAMPTZ NOT NULL, time_limit_seconds INTEGER NOT NULL, violations_used INTEGER NOT NULL DEFAULT 0, last_violation_at TIMESTAMPTZ, session_id BIGINT REFERENCES sessions(id), overall INTEGER, skill_scores JSONB, taken_at TIMESTAMPTZ, integrity_status TEXT NOT NULL DEFAULT 'ok', integrity_reasons TEXT[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS drives (id BIGSERIAL PRIMARY KEY, company TEXT NOT NULL, role TEXT NOT NULL, date DATE NOT NULL, deadline DATE NOT NULL, min_cgpa NUMERIC(3,1), min_score INTEGER, branches TEXT[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS shortlists (placement_id BIGINT REFERENCES users(id), student_id BIGINT REFERENCES users(id), PRIMARY KEY(placement_id,student_id));
CREATE TABLE IF NOT EXISTS drive_responses (drive_id BIGINT NOT NULL REFERENCES drives(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(drive_id,user_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_attempt_per_user ON attempts(user_id) WHERE status='in_progress';
CREATE INDEX IF NOT EXISTS attempts_user_idx ON attempts(user_id);
CREATE INDEX IF NOT EXISTS attempts_session_idx ON attempts(session_id);
CREATE INDEX IF NOT EXISTS questions_skill_idx ON questions(skill);
